import { trpc } from "@/lib/trpc";
import { Activity, ArrowDownToLine, ArrowRight, Bell, BookOpen, Bot, BrainCircuit, Check, ChevronLeft, ChevronRight, CircleAlert, CircleUserRound, Clock3, Cloud, Command, Compass, Crosshair, Database, FileStack, FileText, FlaskConical, Gauge, Globe2, Grid3X3, HelpCircle, Info, KeyRound, Layers3, LayoutDashboard, MapPinned, Maximize2, Menu, Mic, Move, Network, Orbit, PanelRightClose, Radar, Radio, RotateCcw, RotateCw, Ruler, Satellite, ScanSearch, Search, Send, Settings, ShieldCheck, Sparkles, SunMoon, UploadCloud, Waves, X, Zap, ZoomIn, ZoomOut } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
